INSERT INTO dms_order_finance (order_id, order_no, pay_amount, refund_amount, net_pay_amount, product_cost, bonus_amount,
    company_share_amount, company_profit, risk_status, remark)
SELECT #{finance.orderId}, #{finance.orderNo}, #{finance.payAmount}, #{finance.refundAmount}, #{finance.netPayAmount},
    #{finance.productCost}, #{finance.bonusAmount}, #{finance.companyShareAmount}, #{finance.companyProfit},
    #{finance.riskStatus}, #{finance.remark}
FROM dms_shop_order scoped_order
WHERE scoped_order.id = #{finance.orderId}
  AND COALESCE(scoped_order.tenant_id, 1) = #{tenantId}
